actions.script:
def esc = { s -> def v = s == null ? '' : s.toString(); if (!(s instanceof Number) && v ==~ /(?s)^[\s]*[=+@-].*/) v = "'" + v; '"' + v.replace('"','""') + '"' }
def sb = new StringBuilder()
sb.append("Asset ID,Product Name,SKU,Category,Batch/Lot,Supplier,Expiry Date,Days Left,Quantity,Value at Risk,Valuation Basis\r\n")
// expiry-risk §9 bulk: when specific rows are selected (Export Selected), narrow the export to them.
def _rows = (_ex.expiringAssets ?: [])
def _sel = (ec.context.selIds ?: '').toString().trim()
if (_sel) { def _ids = _sel.split(',').findAll { it }.collect { it.trim() }.toSet(); _rows = _rows.findAll { _ids.contains((it.assetId ?: '').toString()) } }
for (def r : _rows) {
    def _basis = (r.valueBasis == 'MRP') ? 'MRP (retail)' : (r.valueBasis == 'unvalued' ? 'not valued' : 'cost')
    def _days = r.daysToExpiry
    def _exp = r.expiryDate ? ec.l10n.format(r.expiryDate, 'yyyy-MM-dd') : ''
    sb.append([esc(r.assetId), esc(r.productName), esc(r.pseudoId), esc(r.category), esc(r.batchNumber), esc(r.supplierName), esc(_exp), esc(_days), esc(r.quantity), esc(r.value), esc(_basis)].join(',')).append("\r\n")
}
ec.web.response.setContentType("text/csv; charset=UTF-8")
ec.web.response.addHeader("Content-Disposition", "attachment; filename=\"expiry-risk-report.csv\"")
def w = ec.web.response.getWriter(); w.write(sb.toString()); w.flush()

def _ua = ec.entity.find("moqui.security.UserAccount").condition("userId", ec.user.userId).disableAuthz().one()
def _to = _ua?.emailAddress
if (!_to) { ec.message.addError("Your account has no email address on file — add one in your profile to email reports."); return }
def _orgRec = ec.entity.find("mantle.party.Organization").condition("partyId", _org).disableAuthz().one()
def _cnt = (_ex.expiringAssets ?: []).size()
try {
    ec.service.sync().name("org.moqui.impl.EmailServices.send#EmailTemplate").parameters([
        emailTemplateId:"EXPIRY_RISK_REPORT", toAddresses:_to.toString().trim(),
        bodyParameters:[orgName:(_orgRec?.organizationName ?: 'Your organization'), count:_cnt, days:(withinDays ?: '90'), reportRows:(_ex.expiringAssets ?: []),
                        valueAtRisk:(_ex.totalExpiryValue ?: 0),
                        dashboardUrl:ec.web.getWebappRootUrl(false, null)+"/apps/zenith/Inventory/ExpiryDashboard"]]).disableAuthz().call()
    if (ec.message.hasError()) return
    ec.message.addMessage("Expiry Risk report emailed to " + _to + " (" + _cnt + " lot" + (_cnt == 1 ? '' : 's') + ").")
} catch (Exception _ee) { ec.message.addError("Couldn't send the email right now: " + _ee.message) }

def _nm = (viewName ?: '').toString().trim()
if (!_nm || _nm.length() > 80) { ec.message.addError("Enter a name for the view."); return }
def _list = []
def _raw = ec.user.getPreference('EXPIRY_SAVED_VIEWS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'))
if (_raw) { try { def parsed = new groovy.json.JsonSlurper().parseText(_raw.toString()); _list = parsed instanceof List ? parsed.findAll { it instanceof Map && it.name instanceof String } : [] } catch (Exception _e) { _list = [] } }
_list = _list.findAll { it?.name != _nm }
_list.add([name:_nm, searchText:(searchText ?: ''), withinDays:(withinDays ?: ''),
           categoryFilter:(categoryFilter ?: ''), supplierFilter:(supplierFilter ?: ''), daysBucket:(daysBucket ?: ''), orderByField:(orderByField ?: 'expiryDate'), pageSize:(pageSize ?: '20')])
if (_list.size() > 20) _list = new ArrayList(_list.subList(_list.size()-20, _list.size()))
ec.user.setPreference('EXPIRY_SAVED_VIEWS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'), groovy.json.JsonOutput.toJson(_list))
ec.message.addMessage("Saved view “" + _nm + "”.")

def _nm = (viewName ?: '').toString().trim()
def _list = []
def _raw = ec.user.getPreference('EXPIRY_SAVED_VIEWS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'))
if (_raw) { try { def parsed = new groovy.json.JsonSlurper().parseText(_raw.toString()); _list = parsed instanceof List ? parsed.findAll { it instanceof Map && it.name instanceof String } : [] } catch (Exception _e) { _list = [] } }
_list = _list.findAll { it?.name != _nm }
ec.user.setPreference('EXPIRY_SAVED_VIEWS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'), groovy.json.JsonOutput.toJson(_list))
ec.message.addMessage("Removed view “" + _nm + "”.")

def _keys = ['sku','batch','supplier','status','quantity','value']
def _shown = { k -> def v = context.get('col_' + k); (v == 'Y' || v == true || v == 'true') }
def _hidden = _keys.findAll { !_shown(it) }
ec.user.setPreference('EXPIRY_HIDDEN_COLS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'), _hidden.join(','))
ec.message.addMessage("Columns updated.")

            def _ad = (alertCfg?.alertDays ?: 30) as Integer
            alertDays = _ad.toString()
            alertEnabled = alertCfg?.alertEnabled ?: 'Y'
            alertEmail = alertCfg?.alertEmail ?: 'N'
            def _items = (expiryOut?.expiringAssets ?: []).findAll { it.daysToExpiry != null && (it.daysToExpiry as Integer) <= _ad }
            alertCount = _items.size()
            def _av = BigDecimal.ZERO
            for (def r : _items) { _av = _av.add(r.value ?: BigDecimal.ZERO) }
            alertValue = _av

            // expiry-risk §10: paginate the sorted list (20/page). The stat cards + tier chips use the FULL list;
            // only the table shows one page. Filters + sort are preserved in the page links. (CSV/PDF export still
            // returns the full list.)
            def _all = (expiryOut?.expiringAssets ?: [])
            expiryRowCount = _all.size()
            expiryCapped = false
            def _pgSize = ['20','50','100'].contains((ec.context.pageSize ?: '20').toString()) ? (ec.context.pageSize as Integer ?: 20) : 20
            int _pgIdx = 0
            try { _pgIdx = ((ec.context.pageIndex ?: '0').toString().trim() ?: '0') as Integer } catch (Exception _pe) { _pgIdx = 0 }
            int _pgCount = (expiryRowCount <= 0) ? 1 : ((int)((expiryRowCount - 1) / _pgSize) + 1)
            if (_pgIdx < 0) _pgIdx = 0
            if (_pgIdx >= _pgCount) _pgIdx = _pgCount - 1
            int _pgFrom = _pgIdx * _pgSize
            int _pgTo = Math.min(_pgFrom + _pgSize, expiryRowCount)
            displayAssets = (expiryRowCount > 0) ? new ArrayList(_all.subList(_pgFrom, _pgTo)) : _all
            pgIndex = _pgIdx; pgCount = _pgCount; pgSize = _pgSize
            pgShowFrom = (expiryRowCount <= 0) ? 0 : (_pgFrom + 1); pgShowTo = _pgTo; pgTotal = expiryRowCount

            // ZE-INV expiry-risk §5.2/§7: derive the "Expired" KPI + tier-bucket counts from the ALREADY-LOADED
            // list — real data (daysToExpiry comes from get#ExpiryRisk), no fabrication, no extra query.
            def _de = { r -> (r.daysToExpiry != null) ? (r.daysToExpiry as Integer) : 999 }
            def riskSummary = expiryOut.summary
            expiredCount = riskSummary.expiredCount
            expiredValue = riskSummary.expiredValue
            vaRItems = riskSummary.riskCount
            vaRUnitsDisp = ec.l10n.format(riskSummary.riskUnits, '#,##0.######')
            expiredUnitsDisp = ec.l10n.format(riskSummary.expiredUnits, '#,##0.######')
            vaRValueDisp = com.zenith.Fmt.regroup(ec.l10n.format(riskSummary.riskValue, '#,##0.00'))
            expiredValueDisp = com.zenith.Fmt.regroup(ec.l10n.format(riskSummary.expiredValue, '#,##0.00'))
            expiredColor = (expiredCount > 0) ? '#DC2626' : '#111827'

            // §7: saved views (per-user preference, JSON list of named filter-sets)
            savedViews = []
            def _svRaw = ec.user.getPreference('EXPIRY_SAVED_VIEWS_' + ec.user.getPreference('ACTIVE_ORGANIZATION'))
            if (_svRaw) { try { def parsed = new groovy.json.JsonSlurper().parseText(_svRaw.toString()); savedViews = parsed instanceof List ? parsed.findAll { it instanceof Map && it.name instanceof String } : [] } catch (Exception _sve) { savedViews = [] } }

            // §8: columns picker — hidden set + the checkbox defaults + the nth-child hide CSS (/apps only).
            def _hcRaw = (ec.user.getPreference('EXPIRY_HIDDEN_COLS_' + ec.user.getPreference('ACTIVE_ORGANIZATION')) ?: '').toString()
            def _hcSet = _hcRaw.split(',').findAll { it }.toSet()
            col_sku = _hcSet.contains('sku') ? 'N' : 'Y'
            col_batch = _hcSet.contains('batch') ? 'N' : 'Y'
            col_supplier = _hcSet.contains('supplier') ? 'N' : 'Y'
            col_status = _hcSet.contains('status') ? 'N' : 'Y'
            col_quantity = _hcSet.contains('quantity') ? 'N' : 'Y'
            col_value = _hcSet.contains('value') ? 'N' : 'Y'
            expiryColumnClasses = _hcSet.findAll { it in ['sku','batch','supplier','status','quantity','value'] }.collect { 'er-hide-' + it }.join(' ')
            expiryBaseUrl = ec.web.request.requestURI.startsWith('/qapps/') ? '/qapps/zenith/Inventory/ExpiryDashboard' : '/apps/zenith/Inventory/ExpiryDashboard'

row-actions.script:
def nowLong = ec.user.nowTimestamp.getTime()
def expLong = expiryDate?.getTime() ?: 0
// Calendar-day classification is supplied by the shared report service.
isExpired = daysToExpiry < 0
unitLabel = [PCS:'pcs',NOS:'nos',KGS:'kg',MTR:'m',LTR:'l',ROL:'rolls'][uqcEnumId] ?: (uqcEnumId ?: 'units')
// expiry-risk §9: per-row overflow (⋮) menu — safe secondary navigations (no destructive
// default; Edit + the qty-to-zero write-off already live in the inline Edit dialog).
kebabHtml = '<details class="er-kebab"><summary class="er-kebab-btn" title="More actions">&#8942;</summary><div class="er-kebab-menu"><a href="' + expiryBaseUrl.replace('/ExpiryDashboard','/EditProduct') + '?productId=' + java.net.URLEncoder.encode((productId ?: '').toString(),'UTF-8') + '">View product</a><a href="' + expiryBaseUrl.replace('/ExpiryDashboard','/StockAdjustments') + '">Adjust stock</a></div></details>'
